/**
 * Per-video configuration. One of the two files you edit for each topic (the other is script/narration.txt).
 * Sentence ids (S01…) come from timeline.ts generated by scripts/tts_build.py. The chapter count and titles come from the `# CHAPTER n Title` lines in narration.txt.
 */
export type HudEntry = {fromS: string; toS: string; text: string; tech?: string; fromOffset?: number; toOffset?: number; w?: number};
export type RailSpec = {steps: string[]; switchS: string[]; fromS: string; toS: string};
export const VIDEO = {
  slug: 'demo', // asset folder public/assets/<slug>/ (tts_build.py writes audio.wav here)
  /**
   * Video language: 'zh' Chinese (default) or 'en' English.
   * Affects the voice engine (tts_build.py's TTS_ENGINE=auto also detects the language from the narration), whether titles and chapter cards are narrowed (Latin text is not),
   * the baseline compensation of centered text (CJK −2 / Latin 0), and the length budgets for copy and subtitle chunks (see reference/narration-storyboard.md §5).
   */
  lang: 'zh' as 'zh' | 'en',
  /**
   * Backdrop: 'stars' star field with a fog gradient (default, the sample's style) or 'dots' dot wave (ported from video-talkcraft dot-field-wave, `common/DotFieldBg.tsx`).
   * The two are mutually exclusive. A BG_Gn override in a shot (`stars:'none'` turns the backdrop off) works with either. frame_metrics.py removes the backdrop using this value before measuring.
   */
  bg: 'stars' as 'stars' | 'dots',
  /**
   * Opening title. Chinese videos: big uses the wide Audiowide face (abbreviations or English words), rest uses Noto 900 (the Chinese part), en is the full English name, and tagline is a one-line hook.
   * English videos: leave rest as '' (not shown), put the main word or abbreviation in big, put the full name or subtitle in en, and use tagline as a one-line hook.
   */
  title: {big: 'RAG', rest: '与知识库', en: 'Retrieval-Augmented Generation', tagline: '让大模型开卷考试'},
  /** Closing credit card (content fades to black, then appears about 2 s after the final subtitle. aboveBar layer. Set to null if not needed) */
  credit: {kicker: 'BASED ON', title: 'Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks', byline: 'Lewis et al. · NeurIPS 2020', note: 'all visuals drawn in code'} as {kicker: string; title: string; byline: string; note: string} | null,
  /** English subtitle for each chapter (in order, matching CHAPTER 1..n in the narration. Chapter cards show it from chapter 2 on) */
  chapterTech: ['Why RAG', 'Indexing', 'Retrieval & Generation', 'Evaluation & Advanced RAG'],
  /** Top HUD capsule (current section name): keyed by sentence-id ranges. Adjacent entries join with no gap, and it fades out automatically across chapter cards. */
  hud: [
    {fromS: 'S01', toS: 'S05', text: '大模型的短板'},
    {fromS: 'S06', toS: 'S07', text: '开卷考试'},
    {fromS: 'S08', toS: 'S10', text: 'RAG', tech: 'Retrieval-Augmented Generation'},
  ] as HudEntry[],
  /** Flow track (optional; at most one per chapter, up to five steps): y118–162. The current step is purple, completed steps are grey-filled, and upcoming steps have grey borders. Chapters with a track have their content area at y175–620 */
  rails: [
    {steps: ['解析', '切块', '向量化', '建索引', '更新'], switchS: ['S12', 'S13', 'S16', 'S18', 'S20'], fromS: 'S12', toS: 'S20'},
  ] as RailSpec[],
  /** Opening length in frames (set by tts_build's LEAD + CHAPTER_GAP, usually 85), and the ending blackout */
  endingFade: 30,
};
